printf '%s\n' 'import argparse' 'import json' 'import sys' '' 'parser = argparse.ArgumentParser(description="Build the settings for one environment")' 'parser.add_argument("config", help="path to the JSON config")' 'parser.add_argument("--env", choices=["dev", "staging", "prod"], default="dev", help="environment to use")' 'args = parser.parse_args()' '' 'try:' '    with open(args.config) as f:' '        cfg = json.load(f)' 'except (OSError, ValueError) as err:' '    sys.exit("error: cannot read %s: %s" % (args.config, err))' 'missing = [key for key in ("app", "defaults") if key not in cfg]' 'if missing:' '    sys.exit("error: missing key: " + ", ".join(missing))' '' 'merged = {**cfg["defaults"], **cfg.get("environments", {}).get(args.env, {})}' 'print(json.dumps(merged, indent=2, sort_keys=True))' > build_config.py
